SELECT event.club_event_id, event.calendar_event_id, event.target_scope_code, event.team_id, team.name AS team_name, event.title, event.description, event.place, event.start_dttm, event.end_dttm, event.check_in_start_dttm, event.check_in_end_dttm, event.status_code, (SELECT COUNT(*) FROM event_attendance attendance WHERE attendance.club_event_id = event.club_event_id) AS target_count FROM club_event event LEFT JOIN team ON team.team_id = event.team_id WHERE event.deleted_dttm IS NULL
AND event.status_code = #{status}
AND event.end_dttm >= #{rangeStart}
AND event.start_dttm < #{rangeEnd}
ORDER BY event.start_dttm DESC, event.club_event_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT event_attendance_id, club_event_id, member_id, status_code, processed_by_member_id, processed_dttm, reason, created_dttm, updated_dttm FROM event_attendance WHERE club_event_id = #{clubEventId} AND event_attendance_id IN
#{eventAttendanceId}
ORDER BY event_attendance_id FOR UPDATE

SELECT attendance.event_attendance_id, attendance.member_id, target.name AS member_name, target.team_id, team.name AS team_name, attendance.status_code, processor.name AS processed_by_name, attendance.processed_dttm, attendance.reason FROM event_attendance attendance JOIN club_event event ON event.club_event_id = attendance.club_event_id JOIN member target ON target.member_id = attendance.member_id JOIN team ON team.team_id = target.team_id LEFT JOIN member processor ON processor.member_id = attendance.processed_by_member_id WHERE attendance.club_event_id = #{clubEventId} AND event.deleted_dttm IS NULL
AND attendance.status_code = #{status}
ORDER BY team.display_order, target.name, target.member_id

